import type { ProjectApplicationStatus } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge/index';

interface ApplicationStatusEntry {
  label: string;
  variant: BadgeVariants;
}

// Key order defines the user-visible filter order (Applied, Approved, Rejected).
export const applicationsStatusConfig: Record<ProjectApplicationStatus, ApplicationStatusEntry> = {
  applied: { label: 'Applied', variant: 'info' },
  approved: { label: 'Approved', variant: 'success' },
  rejected: { label: 'Rejected', variant: 'destructive' },
};

const defaultApplicationStatus: ApplicationStatusEntry = { label: '', variant: 'default' };

export function getApplicationStatus(status: ProjectApplicationStatus): ApplicationStatusEntry {
  return applicationsStatusConfig[status] ?? { ...defaultApplicationStatus, label: snakeCaseToCapitalizedCase(status) };
}

export const applicationsStatuses: SelectItem<ProjectApplicationStatus>[] = Object.entries(
  applicationsStatusConfig
).map(([value, { label }]) => ({ value: value as ProjectApplicationStatus, name: label }));
